mapper.update:
UPDATE imp_arrival_acceptance
SET status = #{query.newStatus},
    evidence_id = #{query.evidenceId},
    evidence_revision = #{query.evidenceRevision},
    version = version + 1,
    updater = CAST(#{query.actorUserId} AS CHAR),
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.arrivalAcceptanceId}
  AND status = #{query.expectedStatus}
  AND version = #{query.expectedVersion}
  AND deleted = b'0'

